import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/Shell.html","title":"Shell","lang":"en-US","frontmatter":{},"git":{"createdTime":1641526952000,"updatedTime":1759318871000,"contributors":[{"name":"Kazuma Arino","username":"","email":"hogeika2@gmail.com","commits":10}]},"readingTime":{"minutes":0.81,"words":244},"filePathRelative":"Shell.md"}`),a={name:`Shell.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="shell" tabindex="-1"><a class="header-anchor" href="#shell"><span>Shell</span></a></h1><p>シェル関連を置くところ。<a href="./sed.html">sed</a>や<a href="./awk.html">awk</a>も関係しがち。<a href="./技術的なメモ.html">技術的なメモ</a>。</p><h2 id="関連リンク" tabindex="-1"><a class="header-anchor" href="#関連リンク"><span>関連リンク</span></a></h2><ul><li><a href="./Unix的.html">Unix的</a></li><li><a href="./zx.html">zx</a></li><li><a href="./Nushell.html">Nushell</a></li><li><a href="./OilShell.html">OilShell</a></li></ul><h2 id="コマンドの記録" tabindex="-1"><a class="header-anchor" href="#コマンドの記録"><span>コマンドの記録</span></a></h2><ul><li><a href="https://stackoverflow.com/questions/30249853/save-zsh-history-to-persistent-history" target="_blank" rel="noopener noreferrer">bash - Save Zsh history to ~/.persistent_history - Stack Overflow</a></li><li><a href="https://eli.thegreenplace.net/2013/06/11/keeping-persistent-history-in-bash" target="_blank" rel="noopener noreferrer">Keeping persistent history in bash - Eli Bendersky&#39;s website</a></li><li><a href="https://spin.atomicobject.com/2016/05/28/log-bash-history/" target="_blank" rel="noopener noreferrer">How (and Why) to Log Your Entire Bash History</a></li></ul><h2 id="zshでのヒストリの保存" tabindex="-1"><a class="header-anchor" href="#zshでのヒストリの保存"><span>zshでのヒストリの保存</span></a></h2><p>上記のstackoverflowのはgawkの所でエラーが出て動かなかった。ダブルクオートにエスケープが必要そうな気がするが、つけたら今度はdateでエラーになったので何かが間違ってそう。</p><p>という事でbashのブログからリンクされてた<a href="https://askubuntu.com/questions/23630/how-do-you-share-history-between-terminals-in-zsh/23631#23631" target="_blank" rel="noopener noreferrer">command line - How do you share history between terminals in zsh? - Ask Ubuntu</a>と、保存される方の数だけ増やすという事で以下にする。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">setopt share_history</span>
<span class="line">export SAVEHIST=1000000000</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>これで良さそう。</p><p>日付を表示するのは<code>history -i</code>。 全部表示するなら<code>history -i 0</code>。</p><h2 id="ln-はソースが先、destがあと" tabindex="-1"><a class="header-anchor" href="#ln-はソースが先、destがあと"><span>ln はソースが先、destがあと</span></a></h2><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ ln -s ../../go_related/gnugo gnugo-3.8</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="ディレクトリだけls、ファイルだけls" tabindex="-1"><a class="header-anchor" href="#ディレクトリだけls、ファイルだけls"><span>ディレクトリだけls、ファイルだけls</span></a></h2><p>毎回やり方がわからなくてググるのでメモ。 ディレクトリだけのlsは以下。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ ls -d */</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>一行ごとに改行して欲しい時は-1。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ ls -1d */</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>ファイルだけのlsは以下。（オプション無いのか）</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$  ls -p | grep -v /</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="雑多なメモ" tabindex="-1"><a class="header-anchor" href="#雑多なメモ"><span>雑多なメモ</span></a></h2><ul><li><a href="https://the.exa.website/" target="_blank" rel="noopener noreferrer">exa · a modern replacement for ls</a> lsの代替らしい</li><li><a href="./OilShell.html">OilShell</a></li><li><a href="https://github.com/google/zx" target="_blank" rel="noopener noreferrer">google/zx: A tool for writing better scripts</a></li></ul><h2 id="シェルの再起動" tabindex="-1"><a class="header-anchor" href="#シェルの再起動"><span>シェルの再起動</span></a></h2><p>良くやり方を忘れるので</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ exec $SHELL -l</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="bcの小数計算" tabindex="-1"><a class="header-anchor" href="#bcの小数計算"><span>bcの小数計算</span></a></h2><p>lオプションでできる。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ echo &quot;106.2/103.3&quot; | bc -l</span>
<span class="line">1.02807357212003872216</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_16進数まわりのprintf" tabindex="-1"><a class="header-anchor" href="#_16進数まわりのprintf"><span>16進数まわりのprintf</span></a></h2><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ printf &quot;%d&quot; 0x72</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="特定のパターンを含まない行だけgrepで" tabindex="-1"><a class="header-anchor" href="#特定のパターンを含まない行だけgrepで"><span>特定のパターンを含まない行だけgrepで</span></a></h2><p>grep -vでできる。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ grep -v &quot;メモ：インクルード ファイル：&quot; debg-out.log &gt; filter.log</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="agで正規表現にしないのは-q" tabindex="-1"><a class="header-anchor" href="#agで正規表現にしないのは-q"><span>agで正規表現にしないのは-Q</span></a></h2><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">ag -Q .mp4</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div>`,36)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};